head.b:skin:
:root{
  --ink:#17211f;--muted:#64716d;--paper:#fbfcfb;--panel:#edf4f1;
  --line:#dce7e2;--accent:#176b55;--accent-dark:#0d4b3b;
  --max:1180px;--radius:22px
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;line-height:1.7}
a{color:var(--accent-dark);text-underline-offset:3px}
img{max-width:100%;height:auto}
.skip-link{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.skip-link:focus{left:18px;top:18px;width:auto;height:auto;background:#111;color:#fff;padding:10px 14px;z-index:9999;border-radius:10px}
.site-header{position:sticky;top:0;z-index:50;background:rgba(251,252,251,.96);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.header-inner{max-width:var(--max);margin:auto;padding:14px 22px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.brand{display:block;text-decoration:none;color:var(--ink);font-weight:900;letter-spacing:-.03em;font-size:1.08rem;line-height:1.25;max-width:600px}
.brand small{display:block;color:var(--muted);font-weight:600;font-size:.72rem;letter-spacing:.02em;margin-top:4px}
.nav{display:flex;gap:16px;flex-wrap:wrap;justify-content:flex-end}
.nav a{font-size:.9rem;text-decoration:none;color:var(--ink);font-weight:750}
.nav a:hover,.brand:hover{color:var(--accent)}
.page-shell{max-width:var(--max);margin:0 auto;padding:20px 22px 56px}
.home-hero{display:grid;grid-template-columns:minmax(0,1fr);gap:18px;padding:clamp(28px,5vw,62px) clamp(22px,5vw,58px);margin:12px 0 36px;background:linear-gradient(135deg,#edf4f1,#f8fbf9);border:1px solid var(--line);border-radius:var(--radius)}
.kicker{font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;font-weight:850;color:var(--accent)}
.home-hero h1{font-size:clamp(2.2rem,5vw,4.25rem);line-height:1.02;letter-spacing:-.05em;margin:.25rem 0 .5rem;max-width:900px}
.lead{font-size:1.08rem;color:#47534f;max-width:820px;margin:0}
.hero-link{display:inline-flex;align-items:center;gap:8px;width:max-content;margin-top:8px;background:#17211f;color:#fff!important;text-decoration:none;padding:13px 18px;border-radius:12px;font-weight:800}
.section-heading{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:0 0 20px}
.section-heading h1,.section-heading h2{font-size:clamp(1.6rem,3vw,2.25rem);line-height:1.15;margin:0;letter-spacing:-.035em}
.section-heading p{color:var(--muted);margin:0;font-size:.95rem}
.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.post-card{display:flex;flex-direction:column;min-width:0;background:#fff;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;box-shadow:0 12px 35px rgba(20,40,32,.045);transition:transform .18s ease,box-shadow .18s ease}
.post-card:hover{transform:translateY(-3px);box-shadow:0 18px 44px rgba(20,40,32,.09)}
.post-card-image{display:flex;align-items:center;justify-content:center;aspect-ratio:16/10;overflow:hidden;background:#edf4f1;text-decoration:none;color:var(--accent-dark)}
.post-card-image img{display:block;width:100%;height:100%;object-fit:cover}
.post-image-placeholder{font-weight:850;letter-spacing:.02em}
.post-card-content{display:flex;flex:1;flex-direction:column;padding:21px}
.post-meta{font-size:.78rem;color:var(--muted);margin-bottom:8px}
.post-card h2,.post-card h3{font-size:1.23rem;line-height:1.28;letter-spacing:-.02em;margin:0 0 10px}
.post-card h2 a,.post-card h3 a{color:var(--ink);text-decoration:none}
.post-card h2 a:hover,.post-card h3 a:hover{color:var(--accent)}
.post-excerpt{color:#4f5a56;font-size:.96rem;margin:0 0 18px}
.read-more{display:inline-flex;gap:7px;align-items:center;margin-top:auto;font-weight:850;text-decoration:none}
.read-more:hover{text-decoration:underline}
.single-post{max-width:920px;margin:24px auto 12px;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:clamp(24px,4.5vw,52px);box-shadow:0 14px 45px rgba(30,22,16,.04)}
.single-post h1{font-size:clamp(2.1rem,4.8vw,3.6rem);line-height:1.06;letter-spacing:-.045em;margin:0 0 1.35rem;overflow-wrap:anywhere}
.single-post .post-body{font-size:1.02rem;line-height:1.85;color:var(--ink);overflow-wrap:anywhere}
.single-post .post-body h2{font-size:clamp(1.45rem,2.7vw,2rem);line-height:1.15;margin:2.1rem 0 .75rem}
.single-post .post-body h3{font-size:clamp(1.18rem,2.2vw,1.45rem);margin:1.7rem 0 .6rem}
.single-post .post-body a{color:var(--accent-dark);text-decoration-thickness:1px;text-underline-offset:3px}
.single-post .post-body ul,.single-post .post-body ol{padding-left:1.35rem}
.single-post .post-body img{height:auto;max-width:100%;border-radius:12px}
.single-post .post-body iframe,.single-post .post-body video{max-width:100%}
.article-end{border-top:1px solid var(--line);margin-top:32px;padding-top:20px}
.article-end a{font-weight:850;text-decoration:none}
.blog-pager{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:28px 0}
.pager-link{display:inline-flex;background:#fff;border:1px solid var(--line);border-radius:11px;padding:11px 15px;text-decoration:none;font-weight:800}
.empty-state{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px;color:var(--muted)}
.site-footer{border-top:1px solid #2a2a2a;background:#1b1b1b;color:#e9e9e9}
.footer-inner{max-width:var(--max);margin:auto;padding:30px 22px;display:grid;gap:16px}
.footer-title{font-size:1.05rem;font-weight:900}
.footer-links{display:flex;flex-wrap:wrap;gap:14px}
.footer-links a{color:#fff;text-decoration:none}
.footer-links a:hover{text-decoration:underline}
.footer-note{font-size:.85rem;color:#bdbdbd;max-width:900px}
#BlogSearch1,#BlogArchive1,#Attribution1,.widget.BlogSearch,.widget.BlogArchive,.widget.Attribution{display:none!important}
@media(max-width:900px){.posts-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.header-inner{align-items:flex-start;flex-direction:column;padding:12px 16px}.nav{justify-content:flex-start;gap:10px}.page-shell{padding:14px 14px 42px}.posts-grid{grid-template-columns:1fr}.home-hero{padding:26px 22px;margin-top:4px}.home-hero h1{font-size:clamp(2.15rem,11vw,3.2rem)}.single-post{padding:22px 18px}.single-post h1{font-size:clamp(2rem,10vw,2.8rem)}.section-heading{align-items:flex-start;flex-direction:column}.blog-pager{align-items:stretch;flex-direction:column}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
